898:     function showPreviewLoading(group: EditorGroup): () => Promise<void> {
899:         // Held past the response, so a superseded render is still holding the overlay
900:         // when its replacement starts and would otherwise hide it on the way out.
901:         const seq = (previewLoadingSeq.get(group.id) ?? 0) + 1;
902:         previewLoadingSeq.set(group.id, seq);
903:         let shownAt = 0;
904:         const timer = window.setTimeout(() => {
905:             if (previewLoadingSeq.get(group.id) !== seq) return;
906:             shownAt = performance.now();
907:             appInstance.setPreviewLoading(group.id, true);
908:         }, PREVIEW_LOADING_DELAY_MS);
909:         return async () => {
910:             window.clearTimeout(timer);
911:             if (shownAt) {
912:                 const held = performance.now() - shownAt;
913:                 if (held < PREVIEW_LOADING_MIN_MS)
914:                     await new Promise(r => setTimeout(r, PREVIEW_LOADING_MIN_MS - held));
915:             }
916:             if (previewLoadingSeq.get(group.id) !== seq) return;
917:             appInstance.setPreviewLoading(group.id, false);
918:         };
