106: /**
107:  * Insert a comment quote on every selected line that needs one, right after its indentation,
108:  * skipping any line that already opens a comment or whose selection lands inside a text region
109:  * mid-line. Returns the 1-based column each quote was inserted at, keyed by line number.
110:  */
111: function ensureCommentPrefixes(
112:     model: monaco.editor.ITextModel,
113:     selections: readonly monaco.Selection[],
114:     edits: monaco.editor.IIdentifiedSingleEditOperation[],
115: ): Map<number, number> {
116:     const startColByLine = new Map<number, number>();
117:     for (const sel of selections) {
118:         const prev = startColByLine.get(sel.startLineNumber);
119:         if (prev === undefined || sel.startColumn < prev) startColByLine.set(sel.startLineNumber, sel.startColumn);
120:     }
121: 
122:     const insertedAt = new Map<number, number>();
123:     for (const [lineNumber, startColumn] of startColByLine) {
124:         const insertCol = getCommentPrefixInsertColumn(model.getLineContent(lineNumber), startColumn - 1);
125:         if (insertCol === null) continue;
126:         edits.push({
127:             range: new monaco.Range(lineNumber, insertCol, lineNumber, insertCol),
128:             text: "'",
129:             forceMoveMarkers: true,
130:         });
131:         insertedAt.set(lineNumber, insertCol);
132:     }
133:     return insertedAt;
134: }
