136: function wrapInline(
137:     editor: monaco.editor.IStandaloneCodeEditor,
138:     bridge: EditorBridge,
139:     type: InlineFormat,
140: ): void {
141:     const model = editor.getModel();
142:     if (!model) return;
143:     const { format, raw } = getContext(editor, bridge);
144:     const [prefix, suffix] = format === 'html' ? HTML_INLINE[type] : MARKDOWN_INLINE[type];
145:     const selections = editor.getSelections() ?? [];
146:     if (selections.length === 0) return;
147: 
148:     const edits: monaco.editor.IIdentifiedSingleEditOperation[] = [];
149:     // Bold/italic/etc. need the line wrapped in a comment for the HTML tags
150:     // to render, same as headings — add one if missing.
151:     const insertedAt = raw ? new Map<number, number>() : ensureCommentPrefixes(model, selections, edits);
152: 
153:     const newSelections: monaco.Selection[] = [];
154: 
155:     for (const sel of selections) {
156:         const shift = insertedAt.has(sel.startLineNumber) ? 1 : 0;
157:         const startCol = sel.startColumn + shift;
158:         const endShift = sel.endLineNumber === sel.startLineNumber ? shift : 0;
159:         const isEmpty = sel.isEmpty();
160:         if (isEmpty) {
161:             const text = prefix + suffix;
162:             edits.push({ range: sel, text, forceMoveMarkers: true });
163:             // After insert, cursor sits between prefix and suffix.
164:             const placedCol = startCol + prefix.length;
165:             newSelections.push(new monaco.Selection(sel.startLineNumber, placedCol, sel.startLineNumber, placedCol));
166:         } else {
167:             const selectedText = model.getValueInRange(sel);
168:             edits.push({ range: sel, text: prefix + selectedText + suffix, forceMoveMarkers: true });
169:             newSelections.push(new monaco.Selection(
170:                 sel.startLineNumber, startCol,
171:                 sel.endLineNumber, sel.endColumn + endShift + prefix.length + suffix.length,
172:             ));
173:         }
174:     }
175: 
176:     editor.executeEdits('calcpad-format-inline', edits, newSelections);
177: }
