179: function insertHeading(
180:     editor: monaco.editor.IStandaloneCodeEditor,
181:     bridge: EditorBridge,
182:     level: number,
183: ): void {
184:     const model = editor.getModel();
185:     if (!model) return;
186:     const { format, raw } = getContext(editor, bridge);
187:     const selections = editor.getSelections() ?? [];
188: 
189:     const edits: monaco.editor.IIdentifiedSingleEditOperation[] = [];
190:     const contentWasEmpty: boolean[] = [];
191:     for (const sel of selections) {
192:         const lineNumber = sel.positionLineNumber;
193:         const lineText = model.getLineContent(lineNumber);
194:         const strippedContent = lineText
195:             .replace(/^<h[1-6]>(.*)<\/h[1-6]>$/, '$1')
196:             .replace(/^#{1,6}\s+(.*)$/, '$1');
197:         contentWasEmpty.push(strippedContent.trim().length === 0);
198:         edits.push({
199:             range: new monaco.Range(lineNumber, 1, lineNumber, lineText.length + 1),
200:             text: buildHeadingLine(lineText, level, format, raw),
201:             forceMoveMarkers: true,
202:         });
203:     }
204:     editor.executeEdits('calcpad-format-heading', edits);
205: 
206:     // Place cursor between tags when the line's content was empty, same as the VS Code extension.
207:     if (format === 'html') {
208:         const closingTag = `</h${level}>`;
209:         const newSelections: monaco.Selection[] = [];
210:         for (let i = 0; i < selections.length; i++) {
211:             if (contentWasEmpty[i]) {
212:                 const lineNumber = selections[i].positionLineNumber;
213:                 const lineLength = model.getLineLength(lineNumber);
214:                 const col = lineLength + 1 - closingTag.length;
215:                 newSelections.push(new monaco.Selection(lineNumber, col, lineNumber, col));
216:             } else {
217:                 newSelections.push(selections[i]);
218:             }
219:         }
220:         editor.setSelections(newSelections);
221:     }
222: }
