300: function toggleComment(editor: monaco.editor.IStandaloneCodeEditor, bridge: EditorBridge): void {
301:     const model = editor.getModel();
302:     if (!model) return;
303:     const sel = editor.getSelection();
304:     if (!sel) return;
305:     const startLine = sel.startLineNumber;
306:     const endLine = sel.endLineNumber;
307: 
308:     if (getParseMode(editor, bridge) !== 'cpd') {
309:         const lineNumbers = Array.from({ length: endLine - startLine + 1 }, (_, i) => startLine + i);
310:         const unwrap = lineNumbers.every(i => isHtmlCommentLine(model.getLineContent(i)));
311:         replaceLines(editor, 'calcpad-toggle-comment', lineNumbers, unwrap ? unwrapHtmlComment : wrapHtmlComment);
312:         return;
313:     }
314: 
315:     let allCommented = true;
316:     for (let i = startLine; i <= endLine; i++) {
317:         if (!model.getLineContent(i).startsWith("'")) { allCommented = false; break; }
318:     }
319: 
320:     const edits: monaco.editor.IIdentifiedSingleEditOperation[] = [];
321:     for (let i = startLine; i <= endLine; i++) {
322:         const text = model.getLineContent(i);
323:         if (allCommented) {
324:             if (text.startsWith("'")) {
325:                 edits.push({ range: new monaco.Range(i, 1, i, 2), text: '', forceMoveMarkers: true });
326:             }
327:         } else {
328:             edits.push({ range: new monaco.Range(i, 1, i, 1), text: "'", forceMoveMarkers: true });
329:         }
330:     }
331:     editor.executeEdits('calcpad-toggle-comment', edits);
332: }
